import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
import { edit_folder_visibility } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    rowInfo: Object,
    viewDetailsDialog: Boolean
  },
  data() {
    return {
      folderVisibility: "",
      cabinetVisbility: "",
      userDetails: [],
      visibilityUsers: [],
      search: "",
      loading2: false,
      folderDescription: ""
    };
  },
  mixins: [get_all_org_users],
  watch: {
    viewDetailsDialog: {
      async handler() {
        if (this.viewDetailsDialog == true) {
          this.visibilityUsers = [];
          this.userDetails = [];
          this.$store.commit("Setnamesearch", "");
          this.folderDescription = this.rowInfo.folderDescritpion;
          await this.get_all_org_users();
          this.fetch_details();
          this.cabinetVisbility = this.rowInfo.folder_visibility.visible_type;
          this.userDetails = this.rowInfo.folder_visibility.visible_type == "RESTRICTED_MEMBERS" ? this.rowInfo.folder_visibility.visible_members : [];
          this.folderVisibility = this.rowInfo.folder_visibility.visible_type == "RESTRICTED_MEMBERS" ? "Restricted Users" + " " + "(" + this.fetch_names(this.rowInfo.folder_visibility.visible_members) + ")" : "All Members";
        }
      },
      immediate: true
    }
  },
  methods: {
    onuserinput(value) {
      if (!value.includes(this.$store.getters.GetUserObj.user.user_id)) {
        value.push(this.$store.getters.GetUserObj.user.user_id);
      }
      this.userDetails = value;
      this.search = "";
    },
    async update_details() {
      this.loading2 = true;
      try {
        let result = await API.graphql(graphqlOperation(edit_folder_visibility, {
          input: {
            folder_id: this.rowInfo.folder_id,
            folder_visibility: this.get_visibility_data(),
            folder_description: this.folderDescription
          }
        }));
        var response = JSON.parse(result.data.edit_folder_visibility);
        this.loading2 = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    // isDisabled(item) {
    //   var data = this.$store.getters.GetUserObj;
    //   return item === data.user.user_id;
    // },
    get_visibility_data() {
      var data = {};
      data = {
        visible_type: this.cabinetVisbility,
        visible_members: this.cabinetVisbility == "RESTRICTED_MEMBERS" ? this.userDetails : []
      };
      return data;
    },
    fetch_details() {
      var data = this.$store.getters.GetUserObj;
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.visibilityUsers.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    clear_value() {
      var data = this.$store.getters.GetUserObj;
      if (this.cabinetVisbility == "ALL_MEMBERS") {
        this.userDetails = [];
      } else {
        var arrayNew = [{
          full_user_name: data.user.full_user_name,
          user_id: data.user.user_id
        }];
        this.userDetails = this.rowInfo.folder_visibility.visible_type == "RESTRICTED_MEMBERS" ? this.rowInfo.folder_visibility.visible_members : arrayNew;

        // console.log(this.userDetails);
      }
    },
    fetch_names(ids) {
      var names = [];
      for (var i = 0; i < ids.length; i++) {
        var id = ids[i];
        for (var j = 0; j < this.orgUsers.length; j++) {
          if (this.orgUsers[j].user_id === id) {
            names.push(this.orgUsers[j].full_user_name);
            break; // Break the inner loop once match is found
          }
        }
      }
      return names;
    },
    close_dialog() {
      this.$emit("clicked", 0);
    }
  }
};
